from django.db import migrations, models


def resync_statuses(apps, schema_editor):
    """
    Recompute every request's status the way PurchaseRequest.derived_status
    does. Until now the status was written by whichever step ran last, so
    delivered purchases sat at «سفارش ثبت شد» and requests whose order was
    cancelled still claimed one. Historical models carry no methods, hence the
    copy of the rules here.
    """
    PurchaseRequest = apps.get_model("commercial", "PurchaseRequest")
    for req in PurchaseRequest.objects.exclude(status="cancelled").iterator():
        live = list(
            req.orders.exclude(status="cancelled").values_list("status", flat=True)
        )
        if live:
            status = "delivered" if all(s == "delivered" for s in live) else "ordered"
        elif req.quotes.filter(is_selected=True).exists():
            status = "awarded"
        elif req.quotes.exists():
            status = "quoting"
        else:
            status = "open"
        if status != req.status:
            PurchaseRequest.objects.filter(pk=req.pk).update(status=status)


